'use strict';

const { readFileSync } = require('node:fs');
const { join } = require('node:path');
const { validateHeaderValue } = require('node:http');

const DEFAULT_UPSTREAM = 'http://192.168.178.2:20128';
const DEFAULT_CONFIG_PATH = join(__dirname, '..', 'config.json');

function validateApiKey(apiKey) {
  if (typeof apiKey !== 'string' || apiKey !== apiKey.trim()) {
    throw new Error('apiKey must be a string without surrounding whitespace');
  }
  try {
    validateHeaderValue('authorization', `Bearer ${apiKey}`);
  } catch {
    // Never include the secret or Node's detailed header error in the message.
    throw new Error('apiKey contains invalid HTTP header characters');
  }
  return apiKey;
}

function loadConfiguration({ env = process.env, configPath = env.PROXY_CONFIG_FILE || DEFAULT_CONFIG_PATH } = {}) {
  let text;
  try {
    text = readFileSync(configPath, 'utf8');
  } catch (error) {
    if (error.code !== 'ENOENT' || env.PROXY_CONFIG_FILE) {
      throw new Error('Cannot read proxy configuration file');
    }
  }

  let config = {};
  if (text !== undefined) {
    try {
      // Windows editors may save UTF-8 files with a BOM.
      config = JSON.parse(text.replace(/^\uFEFF/, ''));
    } catch {
      throw new Error('Proxy configuration must contain valid JSON');
    }
    if (!config || typeof config !== 'object' || Array.isArray(config)) {
      throw new Error('Proxy configuration must be a JSON object');
    }
  }

  if (config.upstreamBaseUrl !== undefined
    && (typeof config.upstreamBaseUrl !== 'string' || !config.upstreamBaseUrl.trim())) {
    throw new Error('upstreamBaseUrl must be a nonempty string');
  }

  return {
    upstreamBaseUrl: env.OMNIROUTE_BASE_URL || config.upstreamBaseUrl || DEFAULT_UPSTREAM,
    apiKey: validateApiKey(config.apiKey === undefined ? '' : config.apiKey),
  };
}

module.exports = { DEFAULT_UPSTREAM, loadConfiguration, validateApiKey };

'use strict';

const http = require('node:http');
const https = require('node:https');
const { pipeline } = require('node:stream');
const { createGunzip, createInflate, createBrotliDecompress } = require('node:zlib');
const { InitialResponseFilter } = require('./sse-filter');

const DEFAULT_UPSTREAM = 'http://192.168.178.2:20128';
const HOP_BY_HOP = new Set([
  'connection', 'keep-alive', 'transfer-encoding', 'upgrade',
  'proxy-authenticate', 'proxy-authorization', 'proxy-connection', 'te', 'trailer',
]);

function forwardHeaders(headers) {
  const excluded = new Set(HOP_BY_HOP);
  for (const token of String(headers.connection || '').split(',')) {
    excluded.add(token.trim().toLowerCase());
  }
  return Object.fromEntries(Object.entries(headers).filter(([name]) => !excluded.has(name.toLowerCase())));
}

function parseUpstream(value) {
  const url = new URL(value);
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.search || url.hash) {
    throw new Error('OMNIROUTE_BASE_URL must be an HTTP(S) URL without credentials, query or fragment');
  }
  return url;
}

function createProxyServer({ upstreamBaseUrl = DEFAULT_UPSTREAM, logger = console } = {}) {
  const upstream = parseUpstream(upstreamBaseUrl);
  const transport = upstream.protocol === 'https:' ? https : http;
  const prefix = upstream.pathname.replace(/\/+$/, '');

  const server = http.createServer((req, res) => {
    const isResponses = req.method === 'POST' && req.url.split('?')[0] === '/v1/responses';
    const headers = forwardHeaders(req.headers);
    headers.host = upstream.host;
    if (isResponses) headers['accept-encoding'] = 'identity';

    let upstreamResponse;
    let clientAborted = false;
    const outgoing = transport.request({
      protocol: upstream.protocol,
      hostname: upstream.hostname.startsWith('[') ? upstream.hostname.slice(1, -1) : upstream.hostname,
      port: upstream.port || undefined,
      method: req.method,
      path: prefix + req.url,
      headers,
    });

    const abort = () => {
      clientAborted = true;
      outgoing.destroy();
      upstreamResponse?.destroy();
    };
    req.on('aborted', abort);
    req.on('error', () => {
      abort();
      res.destroy();
    });
    res.on('close', () => {
      if (!res.writableFinished) abort();
    });

    outgoing.on('error', (error) => {
      if (clientAborted) return;
      // Log only the error code, never URLs, headers or request bodies.
      logger.error(`[proxy] upstream network error (${error.code || 'UNKNOWN'})`);
      if (res.headersSent) {
        res.destroy();
        return;
      }
      res.writeHead(502, { 'content-type': 'application/json; charset=utf-8' });
      res.end(JSON.stringify({
        error: { message: 'OmniRoute upstream unavailable', type: 'proxy_error' },
      }));
      req.unpipe(outgoing);
      req.resume();
    });

    outgoing.on('response', (response) => {
      upstreamResponse = response;
      if (clientAborted) {
        response.destroy();
        return;
      }
      const responseHeaders = forwardHeaders(response.headers);
      const contentType = String(response.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
      let filter = isResponses && contentType === 'text/event-stream';
      const stages = [response];
      const encoding = String(response.headers['content-encoding'] || 'identity').trim().toLowerCase();

      if (filter && encoding !== 'identity') {
        // Defensive fallback if the upstream ignores Accept-Encoding: identity.
        const decompressors = {
          gzip: createGunzip, 'x-gzip': createGunzip,
          deflate: createInflate, br: createBrotliDecompress,
        };
        const decompress = Object.hasOwn(decompressors, encoding) ? decompressors[encoding] : undefined;
        if (decompress) {
          stages.push(decompress());
          delete responseHeaders['content-encoding'];
        } else {
          filter = false; // Unknown encoding: preserve the response, never corrupt it.
          logger.error('[proxy] unsupported SSE content encoding; forwarding unchanged');
        }
      }

      if (filter) {
        delete responseHeaders['content-length'];
        // These validators/digests would describe the unfiltered representation.
        for (const name of ['etag', 'content-md5', 'digest', 'content-digest', 'repr-digest']) {
          delete responseHeaders[name];
        }
        stages.push(new InitialResponseFilter({
          onStrip: () => logger.info('[proxy] stripped invalid initial response.in_progress frame'),
        }));
      }

      res.writeHead(response.statusCode, response.statusMessage, responseHeaders);
      res.flushHeaders();
      pipeline(...stages, res, (error) => {
        if (error && !clientAborted) {
          logger.error(`[proxy] upstream stream error (${error.code || 'UNKNOWN'})`);
        }
      });
    });

    req.pipe(outgoing);
  });

  // LLM streams may be long-lived; do not impose body or socket deadlines.
  server.requestTimeout = 0;
  server.timeout = 0;
  return server;
}

function start() {
  const portText = process.env.PORT || '20129';
  const port = Number(portText);
  if (!/^\d+$/.test(portText) || !Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error('PORT must be an integer between 1 and 65535');
  }
  const upstreamBaseUrl = process.env.OMNIROUTE_BASE_URL || DEFAULT_UPSTREAM;
  const upstream = parseUpstream(upstreamBaseUrl);
  const server = createProxyServer({ upstreamBaseUrl });
  server.on('error', (error) => {
    console.error(`[proxy] server error (${error.code || 'UNKNOWN'})`);
    process.exitCode = 1;
  });
  server.listen(port, '127.0.0.1', () => {
    console.info(`[proxy] listening on http://127.0.0.1:${port}`);
    console.info(`[proxy] upstream: ${upstream.href}`);
  });
  for (const signal of ['SIGINT', 'SIGTERM']) {
    process.once(signal, () => {
      server.close();
      server.closeAllConnections();
    });
  }
  return server;
}

if (require.main === module) {
  try {
    start();
  } catch {
    console.error('[proxy] invalid configuration: check PORT and OMNIROUTE_BASE_URL (HTTP(S), no credentials/query/fragment)');
    process.exitCode = 1;
  }
}

module.exports = { createProxyServer, start };

'use strict';

const http = require('node:http');
const https = require('node:https');
const { pipeline } = require('node:stream');
const { createGunzip, createInflate, createBrotliDecompress } = require('node:zlib');
const { InitialResponseFilter } = require('./sse-filter');
const { DEFAULT_UPSTREAM, loadConfiguration, validateApiKey } = require('./config');

const HOP_BY_HOP = new Set([
  'connection', 'keep-alive', 'transfer-encoding', 'upgrade',
  'proxy-authenticate', 'proxy-authorization', 'proxy-connection', 'te', 'trailer',
]);

function forwardHeaders(headers) {
  const excluded = new Set(HOP_BY_HOP);
  for (const token of String(headers.connection || '').split(',')) {
    excluded.add(token.trim().toLowerCase());
  }
  return Object.fromEntries(Object.entries(headers).filter(([name]) => !excluded.has(name.toLowerCase())));
}

function parseUpstream(value) {
  const url = new URL(value);
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.search || url.hash) {
    throw new Error('OMNIROUTE_BASE_URL must be an HTTP(S) URL without credentials, query or fragment');
  }
  return url;
}

function createProxyServer({ upstreamBaseUrl = DEFAULT_UPSTREAM, apiKey = '', logger = console } = {}) {
  const upstream = parseUpstream(upstreamBaseUrl);
  validateApiKey(apiKey);
  const transport = upstream.protocol === 'https:' ? https : http;
  const prefix = upstream.pathname.replace(/\/+$/, '');

  const server = http.createServer((req, res) => {
    const isResponses = req.method === 'POST' && req.url.split('?')[0] === '/v1/responses';
    const headers = forwardHeaders(req.headers);
    headers.host = upstream.host;
    if (apiKey && headers.authorization === undefined && headers['x-api-key'] === undefined) {
      headers.authorization = `Bearer ${apiKey}`;
    }
    if (isResponses) headers['accept-encoding'] = 'identity';

    let upstreamResponse;
    let clientAborted = false;
    const outgoing = transport.request({
      protocol: upstream.protocol,
      hostname: upstream.hostname.startsWith('[') ? upstream.hostname.slice(1, -1) : upstream.hostname,
      port: upstream.port || undefined,
      method: req.method,
      path: prefix + req.url,
      headers,
    });

    const abort = () => {
      clientAborted = true;
      outgoing.destroy();
      upstreamResponse?.destroy();
    };
    req.on('aborted', abort);
    req.on('error', () => {
      abort();
      res.destroy();
    });
    res.on('close', () => {
      if (!res.writableFinished) abort();
    });

    outgoing.on('error', (error) => {
      if (clientAborted) return;
      // Log only the error code, never URLs, headers or request bodies.
      logger.error(`[proxy] upstream network error (${error.code || 'UNKNOWN'})`);
      if (res.headersSent) {
        res.destroy();
        return;
      }
      res.writeHead(502, { 'content-type': 'application/json; charset=utf-8' });
      res.end(JSON.stringify({
        error: { message: 'OmniRoute upstream unavailable', type: 'proxy_error' },
      }));
      req.unpipe(outgoing);
      req.resume();
    });

    outgoing.on('response', (response) => {
      upstreamResponse = response;
      if (clientAborted) {
        response.destroy();
        return;
      }
      const responseHeaders = forwardHeaders(response.headers);
      const contentType = String(response.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
      let filter = isResponses && contentType === 'text/event-stream';
      const stages = [response];
      const encoding = String(response.headers['content-encoding'] || 'identity').trim().toLowerCase();

      if (filter && encoding !== 'identity') {
        // Defensive fallback if the upstream ignores Accept-Encoding: identity.
        const decompressors = {
          gzip: createGunzip, 'x-gzip': createGunzip,
          deflate: createInflate, br: createBrotliDecompress,
        };
        const decompress = Object.hasOwn(decompressors, encoding) ? decompressors[encoding] : undefined;
        if (decompress) {
          stages.push(decompress());
          delete responseHeaders['content-encoding'];
        } else {
          filter = false; // Unknown encoding: preserve the response, never corrupt it.
          logger.error('[proxy] unsupported SSE content encoding; forwarding unchanged');
        }
      }

      if (filter) {
        delete responseHeaders['content-length'];
        // These validators/digests would describe the unfiltered representation.
        for (const name of ['etag', 'content-md5', 'digest', 'content-digest', 'repr-digest']) {
          delete responseHeaders[name];
        }
        stages.push(new InitialResponseFilter({
          onStrip: () => logger.info('[proxy] stripped invalid initial response.in_progress frame'),
        }));
      }

      res.writeHead(response.statusCode, response.statusMessage, responseHeaders);
      res.flushHeaders();
      pipeline(...stages, res, (error) => {
        if (error && !clientAborted) {
          logger.error(`[proxy] upstream stream error (${error.code || 'UNKNOWN'})`);
        }
      });
    });

    req.pipe(outgoing);
  });

  // LLM streams may be long-lived; do not impose body or socket deadlines.
  server.requestTimeout = 0;
  server.timeout = 0;
  return server;
}

function start() {
  const portText = process.env.PORT || '20129';
  const port = Number(portText);
  if (!/^\d+$/.test(portText) || !Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error('PORT must be an integer between 1 and 65535');
  }
  const { upstreamBaseUrl, apiKey } = loadConfiguration();
  const upstream = parseUpstream(upstreamBaseUrl);
  const server = createProxyServer({ upstreamBaseUrl, apiKey });
  server.on('error', (error) => {
    console.error(`[proxy] server error (${error.code || 'UNKNOWN'})`);
    process.exitCode = 1;
  });
  server.listen(port, '127.0.0.1', () => {
    console.info(`[proxy] listening on http://127.0.0.1:${port}`);
    console.info(`[proxy] upstream: ${upstream.href}`);
  });
  for (const signal of ['SIGINT', 'SIGTERM']) {
    process.once(signal, () => {
      server.close();
      server.closeAllConnections();
    });
  }
  return server;
}

if (require.main === module) {
  try {
    start();
  } catch {
    console.error('[proxy] invalid configuration: check config.json/PROXY_CONFIG_FILE, apiKey, PORT and OMNIROUTE_BASE_URL (HTTP(S), no credentials/query/fragment)');
    process.exitCode = 1;
  }
}

module.exports = { createProxyServer, start };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { mkdtempSync, writeFileSync, rmSync } = require('node:fs');
const { join } = require('node:path');
const { tmpdir } = require('node:os');
const { once } = require('node:events');
const http = require('node:http');
const { loadConfiguration, DEFAULT_UPSTREAM } = require('../src/config');
const { createProxyServer } = require('../src/index');

function configFile(t, content) {
  const directory = mkdtempSync(join(tmpdir(), 'omniroute-config-'));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  const path = join(directory, 'config.json');
  if (content !== undefined) writeFileSync(path, content);
  return path;
}

test('loads upstream URL and API key from JSON', (t) => {
  const configPath = configFile(t, JSON.stringify({ upstreamBaseUrl: 'https://example.com/gateway', apiKey: 'test-secret' }));
  assert.deepEqual(loadConfiguration({ env: {}, configPath }), {
    upstreamBaseUrl: 'https://example.com/gateway', apiKey: 'test-secret',
  });
});

test('environment upstream overrides the file while preserving its API key', (t) => {
  const configPath = configFile(t, JSON.stringify({ upstreamBaseUrl: 'http://file-host', apiKey: 'file-key' }));
  assert.deepEqual(loadConfiguration({ env: { OMNIROUTE_BASE_URL: 'http://env-host' }, configPath }), {
    upstreamBaseUrl: 'http://env-host', apiKey: 'file-key',
  });
});

test('uses defaults without a configuration file or without optional properties', (t) => {
  for (const content of [undefined, '{}']) {
    assert.deepEqual(loadConfiguration({ env: {}, configPath: configFile(t, content) }), {
      upstreamBaseUrl: DEFAULT_UPSTREAM, apiKey: '',
    });
  }
});

test('supports PROXY_CONFIG_FILE and rejects a missing explicitly selected file', (t) => {
  const path = configFile(t, '{"apiKey":"selected-key"}');
  assert.equal(loadConfiguration({ env: { PROXY_CONFIG_FILE: path } }).apiKey, 'selected-key');
  assert.throws(() => loadConfiguration({ env: { PROXY_CONFIG_FILE: path + '.missing' } }), /Cannot read/);
});

test('accepts a UTF-8 BOM in configuration files', (t) => {
  const configPath = configFile(t, '\uFEFF{"apiKey":"test-key"}');
  assert.equal(loadConfiguration({ env: {}, configPath }).apiKey, 'test-key');
});

test('rejects invalid JSON and nonobject roots without revealing content', (t) => {
  for (const content of ['{"apiKey":"private-secret",', 'null', '[]', '42', '"private-secret"']) {
    const configPath = configFile(t, content);
    assert.throws(() => loadConfiguration({ env: {}, configPath }), (error) => {
      assert.doesNotMatch(error.message, /private-secret/);
      return true;
    });
  }
});

test('rejects invalid property types and unsafe API header values', (t) => {
  for (const config of [
    { upstreamBaseUrl: 42 }, { upstreamBaseUrl: '' }, { upstreamBaseUrl: null },
    { apiKey: 42 }, { apiKey: null }, { apiKey: ' private-secret' },
    { apiKey: 'private-secret\r\nx-injected: value' }, { apiKey: 'private-secret\u0000' },
  ]) {
    const configPath = configFile(t, JSON.stringify(config));
    assert.throws(() => loadConfiguration({ env: {}, configPath }), (error) => {
      assert.doesNotMatch(error.message, /private-secret/);
      return true;
    });
  }
});

test('rejects an unsafe direct API-key option before opening a server', () => {
  assert.throws(() => createProxyServer({ apiKey: 'secret\r\ninvalid' }), /invalid HTTP header/);
});

async function listen(t, server) {
  t.after(async () => {
    server.closeAllConnections();
    if (server.listening) await new Promise((resolve) => server.close(resolve));
  });
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  return `http://127.0.0.1:${server.address().port}`;
}

function get(url, headers) {
  return new Promise((resolve, reject) => {
    const req = http.get(url, { headers, agent: false }, (res) => {
      res.resume();
      res.on('error', reject);
      res.on('end', () => resolve(res.statusCode));
    });
    req.on('error', reject);
  });
}

test('file API key is a Bearer fallback and never overrides incoming credentials', { timeout: 10000 }, async (t) => {
  const observations = [];
  const upstream = http.createServer((req, res) => {
    observations.push(req.headers);
    res.end('OK');
  });
  const upstreamBaseUrl = await listen(t, upstream);
  const configPath = configFile(t, JSON.stringify({ upstreamBaseUrl, apiKey: 'file-secret' }));
  const logs = [];
  const logger = { info: (line) => logs.push(line), error: (line) => logs.push(line) };
  const proxy = createProxyServer({ ...loadConfiguration({ env: {}, configPath }), logger });
  const proxyUrl = await listen(t, proxy);

  for (const headers of [
    {}, { authorization: 'Bearer client-secret' }, { 'x-api-key': 'client-key' },
    { authorization: 'Basic client-credentials', 'x-api-key': 'client-key' },
    { authorization: '' }, { 'x-api-key': '' },
  ]) {
    assert.equal(await get(proxyUrl + '/v1/models', headers), 200);
    const forwarded = observations.at(-1);
    const hasAuth = headers.authorization !== undefined || headers['x-api-key'] !== undefined;
    assert.equal(forwarded.authorization, hasAuth ? headers.authorization : 'Bearer file-secret');
    assert.equal(forwarded['x-api-key'], headers['x-api-key']);
  }
  assert.doesNotMatch(logs.join('\n'), /file-secret|client-secret|client-key|client-credentials/);
});

test('empty configured key does not add an Authorization header', { timeout: 10000 }, async (t) => {
  let observed;
  const upstream = http.createServer((req, res) => {
    observed = req.headers;
    res.end('OK');
  });
  const upstreamBaseUrl = await listen(t, upstream);
  const configPath = configFile(t, JSON.stringify({ upstreamBaseUrl, apiKey: '' }));
  const proxy = createProxyServer(loadConfiguration({ env: {}, configPath }));
  const proxyUrl = await listen(t, proxy);
  assert.equal(await get(proxyUrl + '/health', {}), 200);
  assert.equal(observed.authorization, undefined);
});
